(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  const wy1 = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  const sx1 = x + wx1, sy1 = y + wy1;
  const wx2 = Math.sin(sx1 * 0.025 + sy1 * 0.02 + t * 0.15) * 8;
  const wy2 = Math.cos(sx1 * 0.02 - sy1 * 0.025 - t * 0.2) * 8;
  const sx = sx1 + wx2, sy = sy1 + wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.05, 1.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.07, 1.3],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.04, 1.8],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.08, 1.1],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.06, 2.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.05, 1.6],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 0.09, 1.4],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*70, 0.065, 1.8, 0.045, 1.7],
    [200+Math.sin(t*0.5+6)*90, 220+Math.cos(t*0.35+3)*60, 0.095, 2.4, 0.065, 1.2],
    [350+Math.cos(t*0.7+2)*80, 130+Math.sin(t*0.45+5)*80, 0.075, 2.0, 0.055, 1.9]
  ];
  let aS = 0, iS = 0, crossI = 0, harm = 0;
  for (let j = 0; j < src.length; j++) {
    const [sX, sY, f, sp, f2, sp2] = src[j];
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    harm += Math.sin(d*f2 - t*sp2 + j*0.7);
    const j2 = (j + 1) % src.length;
    const d2 = Math.sqrt((sx-src[j2][0])**2 + (sy-src[j2][1])**2);
    crossI += Math.sin(d*f + d2*src[j2][2] - t*(sp+src[j2][3])*0.5) * 0.3;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, harmW = harm/n, crossW = crossI/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08*Math.cos(t*0.1)+sy*0.06*Math.sin(t*0.15)+t*0.5)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.03-ang*2+t*0.8)*Math.cos(dist*0.07+ang*5-t*1.8)*0.3;
  const feed = act + crossW*0.5 + bg*0.3 + spiral1 + spiral2;
  const kill = inh*0.7 - harmW*0.3;
  const reaction = Math.tanh((feed - kill)*2.2);
  let minD = 999, secondD = 999;
  for (const [sX, sY] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    if (d < minD) { secondD = minD; minD = d; }
    else if (d < secondD) secondD = d;
  }
  const cell = (1 - Math.tanh((secondD - minD) * 0.15)) * 0.25;
  const blend = reaction*0.65 + cell*0.2 + harmW*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,85],[18,95,115],[35,150,130],[120,185,120],
    [200,190,80],[225,150,75],[210,100,80],[170,60,90],[100,30,70],[50,18,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8 + Math.sin(reaction*Math.PI)*0.2;
  const edge = Math.abs(reaction)>0.7 ? 1.15 : 1.0;
  const glow = Math.max(0, reaction - 0.5) * 0.4;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*30)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*20)|0)
  ];
}
